import {REVOLT_CAST,REVOLT_ART_IDS,REVOLT_EVENTS,REVOLT_REVELATION,REVOLT_TRAINERS} from './revolt-data.js?v=0.90.52';
import {legalForm,legalMoves} from './route-roster.js?v=0.90.52';
import {claimChoiceReward,choiceRewardText} from './choice-rewards.js?v=0.90.52';
export {REVOLT_CAST,REVOLT_ART_IDS,REVOLT_EVENTS};
export function revoltState(state){state.revolt??={version:1,seen:[],clues:[],goalKnown:false,aid:null};return state.revolt;}
export function revoltStage(state){return state.fates?.['LDR-03']?4:state.fates?.['LDR-02']?3:state.fates?.['LDR-01']?2:1;}
export function canReadRevolt(state,event){return !!event&&revoltStage(state)>=event.stage;}
export function recordRevolt(state,id){const e=REVOLT_EVENTS.find(e=>e.id===id);if(!canReadRevolt(state,e))return false;const q=revoltState(state);if(!q.seen.includes(id))q.seen.push(id);if(e.clue&&!q.clues.includes(e.clue))q.clues.push(e.clue);if(e.reveal&&q.clues.length>=2)q.goalKnown=true;q.doctrine=q.goalKnown?'catastrophic-deterrence':null;return true;}
export function revoltLines(state,event){const q=revoltState(state),texts=event.text.map(text=>event.reveal&&q.goalKnown?text.replace('I will tell you why I sent people there.','You heard my answer at the old court. Bring the other sanctuary accounts; we still need to face what that answer would cost.'):text);if(event.reaction==='grain'&&state.cybressa?.grain)texts.push(state.cybressa.grain==='families'?'The kitchens received the grain. I will give you that much. A good deed does not buy the next field, though.':'You fed the marching column. They call that keeping order. We call it keeping the levy cart moving.');if(event.reaction==='medicine'&&state.hospiceQuest?.recipient)texts.push(state.hospiceQuest.recipient==='nurses'?'You gave the medicine to people your officers called the enemy. That matters. It does not erase the carts your army has taken.':'Your soldiers can return to the front now. The other ward still waits. You chose the fighters again.');if(event.reaction==='fates'){const dead=Object.values(state.fates||{}).filter(f=>f==='EXECUTED').length;texts.push(dead?'You have killed surrendered rulers. Perhaps they deserved judgement. Their farmers have still not been asked what happens next.':'You have spared surrendered rulers. Good. Now ask whether they will stop taking the village’s harvest. Mercy for the powerful must reach further than the cell door.');}if(event.reveal&&q.clues.length>=2)texts.push(...REVOLT_REVELATION);return texts.map(text=>text.replaceAll('{player}',state.playerName||'Aimon'));}
export function revoltAid(state,choice){const q=revoltState(state);if(!q.seen.includes('north-road-cart')||q.aid||!['food','protection'].includes(choice))return false;const key=choice==='food'?'bread':'armedEscorts',cost=choice==='food'?6:2;if((state[key]||0)<cost)return false;state[key]-=cost;q.aid=choice;claimChoiceReward(state,'revolt_cart',choice);return true;}
export function installRevoltTrainers(expansion,voices){for(const r of REVOLT_TRAINERS){if(expansion.trainers.some(t=>t.id===r.id))continue;const person=REVOLT_CAST[r.character];expansion.trainers.push({id:r.id,name:person.name,portraitId:r.character,role:'Common Cause',faction:'Common Cause',nonlethal:true,ai_tier:r.ids.length===6?'Leader-lite':'Advanced',runtimeAuthored:true,team:r.ids.map((id,i)=>{const level=r.level+Math.min(i,2),species_id=legalForm(id,level);return {slot:i+1,species_id,level,current_form_legal_move_ids:legalMoves(species_id,level)};})});voices[r.id]={before:'I do not trust another fighter simply because they speak gently. A controlled match: no killing, and no one here swears to your banner.',after:'You kept your partners under control. I will remember that. It does not make us recruits for your army.',repeat:'Our people are still organising. Listen to them before you draw conclusions about us.'};}}

export function revoltJournal(state){const q=state.revolt;if(!q?.seen?.length)return 'Listen for civilian accounts along the road. The war reaches further than the forts.';const records=q.seen.map(id=>REVOLT_EVENTS.find(e=>e.id===id)).filter(Boolean).map(e=>e.title);return 'The Common Cause · '+q.seen.length+' accounts · '+q.clues.length+' sanctuary clues. '+(q.goalKnown?'Darius seeks legendary and mythic Abyssals as a deterrent: a credible threat of catastrophic retaliation against either army. He believes shared fear of unbearable loss will enforce peace; his companions question whose families would pay if the threat is used.':q.clues.length>=2?'The sanctuary surveys point to a larger plan. Ask Darius in Cossenne what he is searching for.':q.clues.length?'An unsealed sanctuary survey suggests the Common Cause is searching for something. Its purpose is still unclear.':q.seen.some(id=>['dorelem-rumour','cybressa-levy','backwater-speaker'].includes(id))?'Peasants from both sides are organising against both armies. Both authorities denounce their speaker Darius as a heretic. His followers include believers and people who have lost their faith.':'Civilian accounts describe levies and hunger caused by both armies. An unmarked relief effort is taking shape.')+' '+records.join(' · ');}
